import org.eclipse.rdf4j.model.base.CoreDatatype;
import org.eclipse.rdf4j.model.util.Values;
import org.eclipse.rdf4j.sail.lmdb.config.LmdbStoreConfig;
import org.eclipse.rdf4j.sail.lmdb.model.LmdbIRI;
import org.eclipse.rdf4j.sail.lmdb.model.LmdbLiteral;
import org.junit.jupiter.api.io.TempDir;
import org.junit.jupiter.params.ParameterizedTest;
import org.junit.jupiter.params.provider.Arguments;
import org.junit.jupiter.params.provider.MethodSource;

class ValueStoreCoreDatatypeDecodeTest {

	private static final int[] FORMATS = { LmdbStoreFormat.CURRENT_VERSION, LmdbStoreFormat.LEGACY_VERSION };

	private enum LoadPath {
		EAGER,
		LAZY,
		SNAPSHOT_LAZY
	}

	static Stream<Arguments> cases() {
		Stream.Builder<Arguments> builder = Stream.builder();
		for (int format : FORMATS) {
			for (LoadPath path : LoadPath.values()) {
				builder.add(Arguments.of(format, path));
			}
		}
		return builder.build();
	}

	@ParameterizedTest
	@MethodSource("cases")
	void stringLiteralDecodesToCoreDatatypeConstant(int format, LoadPath path, @TempDir Path dataDir) throws Exception {
		assertCoreDatatype(dataDir, format, path, Values.literal("abc"), CoreDatatype.XSD.STRING);
	}

	@ParameterizedTest
	@MethodSource("cases")
	void dateTimeLiteralDecodesToCoreDatatypeConstant(int format, LoadPath path, @TempDir Path dataDir)
			throws Exception {
		assertCoreDatatype(dataDir, format, path,
				Values.literal("2020-01-01T00:00:00Z", CoreDatatype.XSD.DATETIME), CoreDatatype.XSD.DATETIME);
	}

	@ParameterizedTest
	@MethodSource("cases")
	void hugeDecimalLiteralDecodesToCoreDatatypeConstant(int format, LoadPath path, @TempDir Path dataDir)
			throws Exception {
		assertCoreDatatype(dataDir, format, path,
				Values.literal("123456789012345678901234567890123456789.5", CoreDatatype.XSD.DECIMAL),
				CoreDatatype.XSD.DECIMAL);
	}

	@ParameterizedTest
	@MethodSource("cases")
	void hugeIntegerLiteralDecodesToCoreDatatypeConstant(int format, LoadPath path, @TempDir Path dataDir)
			throws Exception {
		assertCoreDatatype(dataDir, format, path,
				Values.literal("123456789012345678901234567890123456789", CoreDatatype.XSD.INTEGER),
				CoreDatatype.XSD.INTEGER);
	}

	@ParameterizedTest
	@MethodSource("cases")
	void languageLiteralDecodesToLangString(int format, LoadPath path, @TempDir Path dataDir) throws Exception {
		assertCoreDatatype(dataDir, format, path, Values.literal("bonjour", "fr"), CoreDatatype.RDF.LANGSTRING);
	}

	@ParameterizedTest
	@MethodSource("cases")
	void customDatatypeStillDecodesToDictionaryIri(int format, LoadPath path, @TempDir Path dataDir) throws Exception {
		IRI datatype = Values.iri("http://example.org/dt");
		Literal expected = Values.literal("custom", datatype);
		load(dataDir, format, path, expected, literal -> {
			assertInstanceOf(LmdbIRI.class, literal.loadedDatatype());
			assertInstanceOf(LmdbIRI.class, literal.getDatatype());
			assertEquals(datatype, literal.getDatatype());
			assertEquals(CoreDatatype.NONE, literal.getCoreDatatype());
			assertEquals(expected, literal);
			assertEquals(expected.hashCode(), literal.hashCode());
		});
	}

	private void assertCoreDatatype(Path dataDir, int format, LoadPath path, Literal expected, CoreDatatype core)
			throws Exception {
		load(dataDir, format, path, expected, literal -> {
			assertEquals(core, literal.getCoreDatatype());
			assertEquals(expected.getLabel(), literal.getLabel());
			assertSame(core.getIri(), literal.getDatatype());
			if (expected.getLanguage().isEmpty()) {
				assertSame(core.getIri(), literal.loadedDatatype());
			}
			assertEquals(expected, literal);
			assertEquals(literal, expected);
			assertEquals(expected.hashCode(), literal.hashCode());
		});
	}

	private interface Check {
		void accept(LmdbLiteral literal);
	}

	private void load(Path dataDir, int format, LoadPath path, Literal literal, Check check) throws Exception {
		var config = new LmdbStoreConfig("spoc,posc").setInlineLiterals(false).setForceSync(false);
		var values = new ValueStore(dataDir.resolve("values").toFile(),
				new StoreProperties().setVersion(Integer.toString(format)), config);
		try (var triples = new TripleStore(dataDir.resolve("triples").toFile(), config, values)) {
			values.startTransaction(true);
			long id = values.storeValue(literal);
			values.commit();
			values.clearCaches();
			LmdbLiteral loaded;
			switch (path) {
			case EAGER:
				loaded = (LmdbLiteral) values.getValue(id);
				check.accept(loaded);
				break;
			case LAZY:
				loaded = (LmdbLiteral) values.getLazyValue(id);
				CoreDatatype before = loaded.getCoreDatatype();
				loaded.init();
				assertEquals(before, loaded.getCoreDatatype(), "core datatype changed across init()");
				check.accept(loaded);
				break;
			default:
				try (var triple = triples.getTxnManager().createReadTxnPinned(triples::getDataRevision);
						var reserved = values.reserveReadSnapshot();
						var snapshot = reserved.start(triple);
						var scope = values.openValueResolutionScope()) {
					loaded = (LmdbLiteral) values.getLazyValue(snapshot, id, ValuePosition.OBJECT, scope);
					CoreDatatype beforeInit = loaded.getCoreDatatype();
					loaded.init();
					assertEquals(beforeInit, loaded.getCoreDatatype(), "core datatype changed across init()");
					check.accept(loaded);
				}
			}
		} finally {
			values.close();
		}
	}
}
